 private static void advancement(ServerLevel level){
  var profile=new com.mojang.authlib.GameProfile(UUID.randomUUID(),"FoolsAdvance");var player=new net.minecraft.server.level.ServerPlayer(level.getServer(),level,profile,net.minecraft.server.level.ClientInformation.createDefault());player.connection=new net.minecraft.server.network.ServerGamePacketListenerImpl(level.getServer(),new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND),player,net.minecraft.server.network.CommonListenerCookie.createInitial(profile,false));var progress=player.getAdvancements();var target=level.getServer().getAdvancements().get(net.minecraft.resources.Identifier.withDefaultNamespace("story/mine_diamond"));require(target!=null,"native Diamonds advancement exists");
  for(var item:List.of(FoolsDiamondContent.DUST,FoolsDiamondContent.ORE.asItem(),FoolsDiamondContent.DEEPSLATE_ORE.asItem())){var stack=new ItemStack(item);player.getInventory().setItem(0,stack);net.minecraft.advancements.triggers.CriteriaTriggers.INVENTORY_CHANGED.trigger(player,player.getInventory(),stack);require(!progress.getOrStartProgress(target).isDone(),"false ore/dust cannot grant genuine diamond progress");}
  var diamond=new ItemStack(Items.DIAMOND);player.getInventory().setItem(0,diamond);net.minecraft.advancements.triggers.CriteriaTriggers.INVENTORY_CHANGED.trigger(player,player.getInventory(),diamond);require(progress.getOrStartProgress(target).isDone(),"real diamond positive advancement control");Blockbranch.LOGGER.info("FOOLS_DIAMOND false pickup advancement=false genuine control=true");
 }
 private static void legacy(ServerLevel level,Path directory)throws Exception{
  long checked=0;int witnesses=0,diamonds=0;java.util.function.Predicate<BlockState> p=FoolsDiamondSmoke::isFools;require(!new OreLayer(1,0,0,8,0,0).maybeHas(p)&&new OreLayer(1,0,0,9,0,0).maybeHas(p)&&new OreLayer(1,0,0,9,0,0).affectsPredicate(p),"new ore predicates are version gated");
  try(var loader=MetallurgySmoke.historicalReader(Path.of(System.getProperty("blockbranch.oldLeadCatalogClasses")).toUri().toURL())){var old=loader.loadClass("blockbranch.realistic.OreLayer");var ctor=old.getConstructor(long.class,int.class,int.class,int.class,int.class,int.class);var bind=old.getMethod("bind",int.class,int.class);var state=old.getMethod("state",int.class,int.class,int.class,int.class,BlockState.class,boolean.class);
   for(long seed:new long[]{424242,1,-17})for(int cx:new int[]{-1,0,1})for(boolean caves:new boolean[]{false,true}){var frozen=bind.invoke(ctor.newInstance(seed,cx,-1,8,65535,65535),64,64);var retained=new OreLayer(seed,cx,-1,8,65535,65535).bind(64,64);var current=new OreLayer(seed,cx,-1,9,65535,65535).bind(64,64);for(int z=0;z<16;z++)for(int x=0;x<16;x++)for(int depth=4;depth<=224;depth+=2){int y=64-depth;var host=(y<0?Blocks.DEEPSLATE:Blocks.STONE).defaultBlockState();var expected=(BlockState)state.invoke(frozen,x,y,z,64,host,caves);require(retained.state(x,y,z,64,host,caves)==expected,"published ore8 remains exact");if(expected.is(Blocks.DIAMOND_ORE)||expected.is(Blocks.DEEPSLATE_DIAMOND_ORE))diamonds++;var next=current.state(x,y,z,64,host,caves);if(expected!=host)require(next==expected,"fools ore cannot replace genuine diamonds or other prior materials");else if(next!=host){require(isFools(next)&&depth>FoolsDiamondVeins.MIN_DEPTH&&depth<FoolsDiamondVeins.MAX_DEPTH,"only fools ore inside its depth band is added");witnesses++;}checked++;}}
   try{old.getMethod("decode",net.minecraft.nbt.CompoundTag.class).invoke(null,new OreLayer(1,0,0,9,0,0).encode());throw new AssertionError("old reader accepted9");}catch(java.lang.reflect.InvocationTargetException expected){require(expected.getCause() instanceof IllegalArgumentException,"prior lead reader safely rejects9");}
   var guard=loader.loadClass("blockbranch.cubic.ColumnWorldFormat").getMethod("check",Path.class,boolean.class,boolean.class,boolean.class);for(boolean decoration:new boolean[]{false,true}){var root=Files.createTempDirectory(directory,"old-lead-guard-");ColumnWorldFormat.check(root,false,decoration,true);var marker=root.resolve("blockbranch-columns.txt");String before=Files.readString(marker);try{guard.invoke(null,root,true,decoration,true);throw new AssertionError("catalog9 reader accepted10");}catch(java.lang.reflect.InvocationTargetException expected){require(expected.getCause() instanceof IllegalStateException,"prior lead reader refuses catalog10");}require(Files.readString(marker).equals(before),"old rejection preserves marker");}
  }
  require(witnesses>0&&diamonds>0,"both false and genuine diamond witnesses are covered");Blockbranch.LOGGER.info("FOOLS_DIAMOND frozenLeadComparisons={} falseWitnesses={} genuineDiamondWitnesses={} oldReaderRejects9=true",checked,witnesses,diamonds);
 }
 private static void natural(ServerLevel level,Path directory)throws Exception{
  if(!(level.getChunkSource().getGenerator() instanceof RealisticGenerator generator))return;if(generator.oreDefinition()<9){require(generator.oreDefinition()>=3&&generator.oreDefinition()<=8,"retained prior definition");Blockbranch.LOGGER.info("FOOLS_DIAMOND prior definition retained; no backfill");return;}require(generator.oreDefinition()>=9,"current fools-compatible definition");var marker=directory.resolve("fools-mined.txt");if(Files.exists(marker)){var v=Files.readString(marker).trim().split(",");var pos=new BlockPos(Integer.parseInt(v[0]),Integer.parseInt(v[1]),Integer.parseInt(v[2]));require(level.getBlockState(pos).isAir()&&isFools(((SparseColumn)level.getChunkAt(pos)).blockbranch$terrain().base().state(pos.getX(),pos.getY(),pos.getZ())),"rare fools mining edit survives relaunch");return;}
  var origin=generator.getOrigin(level.getChunkSource().randomState());for(int dz=0;dz<4;dz++)for(int dx=0;dx<4;dx++){var chunk=level.getChunk(origin.x()+dx,origin.z()+dz);var base=((SparseColumn)chunk).blockbranch$terrain().base();require(base.ores().definition()==generator.oreDefinition(),"actual FULL column retains its saved/current descriptor");var restored=TerrainProfile.decode(base.encode(level.palettedContainerFactory()),level.palettedContainerFactory());for(int z=0;z<16;z++)for(int x=0;x<16;x++)for(int depth=FoolsDiamondVeins.MIN_DEPTH;depth<=FoolsDiamondVeins.MAX_DEPTH;depth++){int y=base.groundHeight(x,z)-depth;var value=base.state(x,y,z);if(!isFools(value))continue;var pos=new BlockPos(chunk.getPos().getMinBlockX()+x,y,chunk.getPos().getMinBlockZ()+z);require(level.getBlockState(pos)==value&&restored.state(x,y,z)==value,"native rare ore agrees with profile roundtrip");level.setBlock(pos,Blocks.AIR.defaultBlockState(),2);Files.writeString(marker,pos.getX()+","+pos.getY()+","+pos.getZ());level.getServer().saveEverything(false,true,true);Blockbranch.LOGGER.info("FOOLS_DIAMOND natural witness={}",pos);return;}}
  throw new AssertionError("no natural fools ore in bounded sixteen-column search");
 }
 private static boolean isFools(BlockState s){return s.is(FoolsDiamondContent.ORE)||s.is(FoolsDiamondContent.DEEPSLATE_ORE);}
 private static void require(boolean value,String message){if(!value)throw new AssertionError(message);}
 private FoolsDiamondSmoke(){}
